using Microsoft.Extensions.FileProviders;
using Yarp.ReverseProxy.Configuration;
var b=WebApplication.CreateBuilder(args);var directory=b.Configuration["Console:DistDirectory"]??throw new InvalidOperationException("Explicit console dist directory required.");var target=b.Configuration["Console:ControlPlaneUrl"]??throw new InvalidOperationException("Explicit control plane URL required.");
b.Services.AddReverseProxy().LoadFromMemory([new RouteConfig{RouteId="management-api",ClusterId="control-plane",Match=new RouteMatch{Path="/api/{**rest}"},Transforms=[new Dictionary<string,string>{{"RequestHeaderOriginalHost","true"}}]}],[new ClusterConfig{ClusterId="control-plane",Destinations=new Dictionary<string,DestinationConfig>{{"control-plane",new(){Address=target}}}}]);
var app=b.Build();var files=new PhysicalFileProvider(Path.GetFullPath(directory));app.UseDefaultFiles(new DefaultFilesOptions{FileProvider=files});app.UseStaticFiles(new StaticFileOptions{FileProvider=files});app.MapReverseProxy();app.MapGet("/health/live",()=>Results.Ok(new{status="live"}));app.MapFallback(async ctx=>{if(ctx.Request.Path.StartsWithSegments("/api")){ctx.Response.StatusCode=404;return;}ctx.Response.ContentType="text/html; charset=utf-8";await ctx.Response.SendFileAsync(Path.Combine(directory,"index.html"));});await app.RunAsync();
